<button type="button" class="btn-primary" data-depot-open="<?=e($id)?>" aria-haspopup="dialog"><?=count($depot['lots'])?(count($depot['lots'])===1?'Voir le lot':'Voir les '.count($depot['lots']).' lots'):'Voir le dépôt'?><i class="bi bi-arrow-right" aria-hidden="true"></i></button></div></article>
<template data-depot-detail="<?=e($id)?>"><header class="campaign-drawer-heading"><div><p class="page-kicker">DÉPÔT · <?=e($farm['code'])?></p><h2 id="depotDetailTitle"><?=e($farm['name'])?></h2><small><?=e($depotKg($depot['available']))?> disponibles · <?=e($depotKg($depot['reserved']))?> réservés</small></div><button type="button" class="modal-close" data-depot-close aria-label="Fermer">×</button></header>
