<dl class="depot-quantities"><div><dt>Physique</dt><dd><?=e($depotKg($stock['physical_quantity_kg']))?></dd></div><div class="is-reserved"><dt>Réservé</dt><dd><?=e($depotKg($stock['reserved_quantity_kg']))?></dd></div><div class="is-available"><dt>Disponible</dt><dd><?=e($depotKg($stock['available_quantity_kg']))?></dd></div></dl>
